-- Answer key: https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_ans.pdf
INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-r05-2023-q01','exam-sg','情報セキュリティ管理基準・標準','standard','single_choice','情報セキュリティ管理基準（平成28年）に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"“ガバナンス基準”，“管理策基準”及び“マネジメント基準”の三つの基準で構成されている。"},{"id":"b","text":"JIS Q 27001:2014（情報セキュリティマネジメントシステム－要求事項）及びJIS Q 27002:2014（情報セキュリティ管理策の実践のための規範）との整合性をとっている。"},{"id":"c","text":"情報セキュリティ対策は，“管理策基準”に挙げられた管理策の中から選択することとしている。"},{"id":"d","text":"トップマネジメントは，“マネジメント基準”に挙げられている事項の中から，自組織に合致する事項を選択して実施することとしている。"}]','"b"','正解はイ。平成28年版の情報セキュリティ管理基準は，JIS Q 27001:2014及びJIS Q 27002:2014との整合性をとっている。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q02','exam-sg','物理セキュリティ・入退室管理','standard','single_choice','入室時と退室時にIDカードを用いて認証を行い，入室時の認証に用いられなかったIDカードでの退室，又は退室時の認証に用いられなかったIDカードでの再入室を許可しない仕組みはどれか。','[{"id":"a","text":"TPMOR（Two Person Minimum Occupancy Rule）"},{"id":"b","text":"アンチパスバック"},{"id":"c","text":"インターロックゲート"},{"id":"d","text":"パニックオープン"}]','"b"','正解はイ。アンチパスバックは入退室の履歴を照合し，同じカードで入室・退室を交互に行うことを求める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q03','exam-sg','デジタルフォレンジックス','standard','single_choice','デジタルフォレンジックスの説明はどれか。','[{"id":"a","text":"サイバー攻撃に関連する脅威情報を標準化された方法で記述し，その脅威情報をセキュリティ対策機器に提供すること"},{"id":"b","text":"受信メールに添付された実行ファイルを動作させたときに，不正な振る舞いがないかどうかをメールボックスへの保存前に確認すること"},{"id":"c","text":"情報セキュリティインシデント発生時に，法的な証拠となるデータを収集し，保管し，調査分析すること"},{"id":"d","text":"内部ネットワークにおいて，通信データを盗聴されないように暗号化すること"}]','"c"','正解はウ。デジタルフォレンジックスは，インシデント時に証拠となるデジタルデータを保全・収集し，調査分析する活動である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q04','exam-sg','暗号・共通鍵暗号方式','standard','single_choice','暗号方式に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"公開鍵暗号方式，共通鍵暗号方式ともに，大きな合成数の素因数分解が困難であることが安全性の根拠である。"},{"id":"b","text":"公開鍵暗号方式では原則としてセッションごとに異なる鍵を利用するが，共通鍵暗号方式では一度生成した鍵を複数のセッションに繰り返し利用する。"},{"id":"c","text":"公開鍵暗号方式は仕様が標準化されているが，共通鍵暗号方式はベンダーによる独自の仕様で実装されることが一般的である。"},{"id":"d","text":"大量のデータを短い時間で暗号化する場合には，公開鍵暗号方式よりも共通鍵暗号方式が適している。"}]','"d"','正解はエ。共通鍵暗号方式は公開鍵暗号方式より処理が高速で，大量データの暗号化に適している。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q05','exam-sg','ハッシュ関数・完全性','standard','single_choice','セキュアハッシュ関数SHA-256でファイルA及びファイルBのハッシュ値を算出すると，全く同じ64桁の16進数となった。この結果から考えられることとして，適切なものはどれか。','[{"id":"a","text":"ファイルAとファイルBの各内容を変更せずに再度ハッシュ値を算出すると，ハッシュ値が異なる。"},{"id":"b","text":"ハッシュ値のデータ量は64バイトである。"},{"id":"c","text":"ファイルAとファイルBを連結させたファイルCのハッシュ値は16進数で128桁になる。"},{"id":"d","text":"ファイルAの内容とファイルBの内容は同じであると考えられる。"}]','"d"','正解はエ。SHA-256は常に256ビット（32バイト，16進数64桁）のハッシュ値を返す。同じ値なら内容が同一と考えられるが，理論上は衝突の可能性がある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q06','exam-sg','メールセキュリティ・SPF','standard','single_choice','迷惑メール対策のSPF（Sender Policy Framework）の仕組みはどれか。','[{"id":"a","text":"送信側ドメインの管理者が正規の送信側メールサーバのIPアドレスをDNSに登録し，受信側メールサーバで参照してIPアドレスを判定する。"},{"id":"b","text":"送信側メールサーバでメッセージにデジタル署名を施し，受信側メールサーバで署名を検証する。"},{"id":"c","text":"第三者が提供するスパムメール送信元IPアドレスのデータベースを参照して判定する。"},{"id":"d","text":"ファイアウォールを通過した要求パケットへの応答かどうかを判断し，動的に迷惑メールの通信を制御する。"}]','"a"','正解はア。SPFはDNSに登録された送信元IPアドレス情報を参照して，送信元が正規のメールサーバかを検証する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q07','exam-sg','Webセキュリティ・SQLインジェクション','standard','single_choice','Webアプリケーションのセキュリティ上の脅威と対策に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"OSコマンドインジェクションを防ぐために，推測困難なセッションIDを使用する。"},{"id":"b","text":"SQLインジェクションを防ぐために，データベースへの問合せを作成する際にプレースホルダを使用する。"},{"id":"c","text":"クロスサイトスクリプティングを防ぐために，Webサーバ内のファイルを外部から直接参照できないようにする。"},{"id":"d","text":"セッションハイジャックを防ぐために，Webアプリケーションからシェルを起動できないようにする。"}]','"b"','正解はイ。プレースホルダを使うと入力値をSQL構文として解釈させず，SQLインジェクションを防ぎやすくなる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q08','exam-sg','法務・電子署名法','standard','single_choice','電子署名法に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"電子署名には，電磁的記録ではなく，コンピュータで処理できないものも含まれる。"},{"id":"b","text":"一定の要件を満たす電子署名が付された電磁的記録には，真正に成立したものと推定される効力が認められる。"},{"id":"c","text":"電子署名の認証業務を行うことができるのは，政府が運営する認証局に限られる。"},{"id":"d","text":"電子署名は共通鍵暗号技術によるものに限られる。"}]','"b"','正解はイ。電子署名法では，一定の要件を満たす電子署名がある電磁的記録について，真正に成立したものと推定する規定がある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q09','exam-sg','インシデント管理・監査','standard','single_choice','情報システムのインシデント管理に対する監査で判明した状況のうち，指摘事項として監査報告書に記載すべきものはどれか。','[{"id":"a","text":"インシデント対応手順が作成され，関係者への周知が図られている。"},{"id":"b","text":"インシデントによるデータベース被害の影響を最小にするため，規程に従ってバックアップを取得している。"},{"id":"c","text":"インシデントの種類や発生箇所，影響度合いに関係なく，連絡・報告ルートが共通になっている。"},{"id":"d","text":"全てのインシデントについて記録を残し，責任者の承認を得ることが定められている。"}]','"c"','正解はウ。インシデントの種類や影響度に応じた連絡・報告ルートが必要であり，一律のルートでは重大事案の迅速なエスカレーションを妨げる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q10','exam-sg','Web・Cookie','standard','single_choice','HTTPのCookieに関する記述のうち，適切なものはどれか。','[{"id":"a","text":"Cookieに含まれる情報はHTTPヘッダの一部として送信される。"},{"id":"b","text":"Cookieに含まれる情報はWebサーバだけに保存される。"},{"id":"c","text":"Cookieに含まれる情報はWebブラウザが全て暗号化して送信する。"},{"id":"d","text":"クライアントがCookieに含まれる情報の有効期限を設定する。"}]','"a"','正解はア。ブラウザはCookieをHTTPリクエストヘッダに含めて送信する。Cookie自体が常に暗号化されるわけではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q11','exam-sg','業務プロセス管理・BPM','standard','single_choice','BPM（Business Process Management）の説明はどれか。','[{"id":"a","text":"生産，物流，販売，財務，人事などの業務情報を一元管理し，経営資源の全体最適を実現する。"},{"id":"b","text":"業務プロセスに分析，設計，実行，改善のマネジメントサイクルを取り入れ，業務プロセスの改善や最適化を継続的に実施する。"},{"id":"c","text":"顧客データベースを基に，販売から保守サービス，問合せやクレーム対応まで顧客関連業務を一貫管理する。"},{"id":"d","text":"部品供給から製品販売までの情報をリアルタイムで交換し，在庫削減とリードタイム短縮を実現する。"}]','"b"','正解はイ。BPMは業務プロセスを分析・設計・実行・改善するサイクルを継続し，業務の最適化を図る手法である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-r05-2023-q12','exam-sg','品質管理・特性要因図','standard','single_choice','品質管理において，結果と原因との関連を整理して，魚の骨のような図にまとめたものはどれか。','[{"id":"a","text":"管理図"},{"id":"b","text":"特性要因図"},{"id":"c","text":"パレート図"},{"id":"d","text":"ヒストグラム"}]','"b"','正解はイ。特性要因図（魚の骨図）は，結果とそれに影響する原因の関係を整理するために用いる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja');
